module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

    parameter IDLE = 2'b00;
    parameter INCREMENT = 2'b01;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wave <= 5'b00000;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (wave == 5'b11111) begin
                        state <= INCREMENT;
                    end else begin
                        wave <= wave + 1;
                    end
                end
                INCREMENT: begin
                    if (wave == 5'b00000) begin
                        state <= IDLE;
                    end else begin
                        wave <= wave - 1;
                    end
                end
                default: begin
                    wave <= 5'b00000;
                    state <= IDLE;
                end
            endcase
        end
    end

endmodule
